begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
select ok(not has_function_privilege('authenticated','public.set_sync_dom_rollout_v2(uuid,boolean,text)','execute'),'a browser cannot enable the producer');
select ok(not has_function_privilege('anon','public.claim_dynamic_render_job_v4(text,integer,integer)','execute'),'anonymous clients cannot claim DOM work');
select ok(not has_function_privilege('authenticated','public.complete_dynamic_dom_job_v2(uuid,text,uuid,jsonb)','execute'),'a browser cannot attest descriptor readiness');
select ok(has_function_privilege('service_role','public.complete_dynamic_dom_job_v2(uuid,text,uuid,jsonb)','execute'),'the fenced worker owns descriptor completion');
select ok(not has_function_privilege('anon','public.request_sync_export_v2(uuid,uuid,uuid)','execute'),'anonymous clients cannot request expensive exports');
select ok(not has_function_privilege('service_role','public.request_sync_export_v2(uuid,uuid,uuid)','execute'),'interactive export keeps human permission checks');
select ok(not has_table_privilege('authenticated','private.sync_dom_rollouts','select'),'rollout records are private');
select ok(not has_table_privilege('authenticated','private.sync_explicit_exports_v2','insert'),'clients cannot bypass export command receipts');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='private.sync_dom_rollouts'::regclass),'rollout RLS defaults to deny');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='private.sync_explicit_exports_v2'::regclass),'export state RLS defaults to deny');
insert into public.tenants(id,name,slug)values('10000000-0000-4000-8000-000000292702','DOM security fixture','s292-dom-security');
set local role authenticated;
select set_config('request.jwt.claim.role','authenticated',true);
select throws_ok($$select public.request_sync_export_v2('10000000-0000-4000-8000-000000292702','20000000-0000-4000-8000-000000292702','30000000-0000-4000-8000-000000292702')$$,'42501',null,'a nonmember cannot queue another tenant export');
select throws_ok($$select public.read_sync_export_v2('10000000-0000-4000-8000-000000292702','20000000-0000-4000-8000-000000292702')$$,'42501',null,'a nonmember cannot inspect another tenant export');
reset role;
set local role service_role;
select set_config('request.jwt.claim.role','service_role',true);
select throws_ok($$select public.set_sync_dom_rollout_v2('10000000-0000-4000-8000-000000292702',true,'unverified')$$,'22023',null,'producer enablement requires an exact verified consumer SHA');
select lives_ok($$select public.set_sync_dom_rollout_v2('10000000-0000-4000-8000-000000292702',true,repeat('a',40))$$,'the authorized rollout records its consumer SHA');
reset role;
select is((select count(*)from private.sync_dom_rollouts where enabled and tenant_id='10000000-0000-4000-8000-000000292702'),1::bigint,'only the named fixture tenant is enabled');
select is(private.published_data_hash_v1('{"syncPlaybackProtocol":2,"generatedAt":"2026-10-25T12:00:00Z","sport":{"fetchedAt":"2026-10-25T12:00:00Z","items":[]}}'),private.published_data_hash_v1('{"syncPlaybackProtocol":2,"generatedAt":"2026-10-25T13:00:00Z","sport":{"fetchedAt":"2026-10-25T13:00:00Z","items":[]}}'),'observation-only refresh keeps DOM semantic identity');
select isnt(private.published_data_hash_v1('{"syncPlaybackProtocol":2,"sport":{"items":[{"score":1}]}}'),private.published_data_hash_v1('{"syncPlaybackProtocol":2,"sport":{"items":[{"score":2}]}}'),'an actual score change advances DOM semantic identity');
select isnt(private.published_data_hash_v1('{"syncPlaybackProtocol":2,"syncEffectiveDay":"2026-10-25"}'),private.published_data_hash_v1('{"syncPlaybackProtocol":2,"syncEffectiveDay":"2026-10-26"}'),'Amsterdam birthday selection day remains semantic');
select is(private.published_data_hash_v1('{"generatedAt":"2026-10-25T12:00:00Z","news":{"articles":[]}}'),private.published_data_hash_before_dom_v2('{"generatedAt":"2026-10-25T12:00:00Z","news":{"articles":[]}}'),'historical protocol hashing remains exact');
select ok(not has_function_privilege('authenticated','public.claim_sync_dom_ready_job_v2(text,integer,integer)','execute'),'DOM lane remains worker-only');
select ok(not has_function_privilege('anon','public.get_worker_queue_hint_v3(integer)','execute'),'compact hints expose no anonymous tenant work');
select is(public.get_worker_queue_hint_v3(3)&32,0,'an empty DOM lane adds no spurious wakeups');
select *from finish();rollback;
